-- H2-05 Pharma OA schema completion. Normal uninstall policy: retain.
CREATE TABLE IF NOT EXISTS pharma_oa_announcements (id VARCHAR(64) PRIMARY KEY, kind VARCHAR(32) NOT NULL, title VARCHAR(255) NOT NULL, content TEXT NOT NULL, status VARCHAR(32) NOT NULL, published_by VARCHAR(64) NOT NULL DEFAULT '', published_at TIMESTAMPTZ NULL, audience_json TEXT NOT NULL, documents_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE INDEX IF NOT EXISTS idx_pharma_announcements_status_published ON pharma_oa_announcements(status,published_at);
CREATE TABLE IF NOT EXISTS pharma_oa_cold_chain_records (id VARCHAR(64) PRIMARY KEY, balance_id VARCHAR(64) NOT NULL, product_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, batch_no VARCHAR(128) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, temperature_celsius DOUBLE PRECISION NOT NULL, humidity_percent DOUBLE PRECISION NOT NULL, min_celsius DOUBLE PRECISION NOT NULL, max_celsius DOUBLE PRECISION NOT NULL, recorded_at TIMESTAMPTZ NOT NULL, source VARCHAR(64) NOT NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE INDEX IF NOT EXISTS idx_pharma_cold_chain_batch_time ON pharma_oa_cold_chain_records(batch_id,recorded_at); CREATE INDEX IF NOT EXISTS idx_pharma_cold_chain_warehouse_time ON pharma_oa_cold_chain_records(warehouse_id,recorded_at);
